/*
 * PlayKit - symbol version script for native app linking.
 * SPDX-License-Identifier: GPL-3.0-or-later
 *
 * Keeps every symbol internal to the executable. The native converter
 * publishes no application exports; exporting one would make it reject the
 * image, and would shadow the same-named system import.
 */

{
    local:
        *;
};
